    const ch = takeChallenge(u, b.chId, 'register', ''), rp = rpInfo(req), c = cfg(); let reg;
    try { reg = W.verifyRegistration((b.credential || {}).response || {}, { challenge: ch.challenge, origins: rp.origins, rpId: rp.rpId }); } catch (e) { fail('REG_FAILED', 'Could not register this device: ' + e.message, 400); }
