    if (b.action === 'approve') cr.status = 'active'; else if (b.action === 'revoke') cr.status = 'revoked'; else fail('ACTION', 'Unknown action', 400);
    await S.put('creds', cr.key, cr); await logEv('device', cr.key, cr.userId, { status: cr.status, by: u.id }); await audit(u, 'biometric device ' + b.action + ' for ' + userName(cr.userId));
