      if (s.kind === 'class' && s.status === 'closed') { const r = A.replayClass(evs); if (!r || r.calcMin !== s.calcMin || r.payMin !== s.payMin || r.hours !== s.hours) bad.push({ sid: s.id, why: 'stored hours (' + s.payMin + ' min, ' + s.hours + ') differ from the logged evidence (' + (r ? r.payMin + ' min, ' + r.hours : '—') + ')' }); }
      if (s.kind === 'class') { const marks = evs.filter(e => e.type === 'mark').length; const docs = Object.values(S.all('att')).filter(m => m.sid === s.id).length; if (docs > marks) bad.push({ sid: s.id, why: 'more attendance marks stored than logged' }); }
